package com.practiq.service;
import java.util.*; import org.springframework.stereotype.Service;
@Service public class GradingService { public Boolean grade(String mode,Map<String,Object> expected,Map<String,Object> actual){if(expected==null)return null;return switch(mode){case "choice"->values(expected).equals(values(actual));case "true_false"->expected.get("value") instanceof Boolean&&actual.get("value") instanceof Boolean?expected.get("value").equals(actual.get("value")):null;case "fill_blank"->blanks(expected,actual);default->null;};} private SortedSet<String> values(Map<String,Object> x){var r=new TreeSet<String>();Object raw=x==null?null:x.get("selected");if(raw instanceof Collection<?> c)c.forEach(v->r.add(String.valueOf(v).trim()));else if(raw!=null)r.add(String.valueOf(raw).trim());return r;} private Boolean blanks(Map<String,Object> e,Map<String,Object>a){List<String>x=list(e),y=list(a);if(x.isEmpty()||y.size()<x.size())return false;for(int i=0;i<x.size();i++)if(!x.get(i).equals(y.get(i)))return false;return true;} private List<String> list(Map<String,Object>x){Object r=x==null?null:x.get("value");Collection<?> c=r instanceof Collection<?> z?z:List.of(r==null?"":r);return c.stream().map(v->String.valueOf(v).trim().toLowerCase().replaceAll("\\s+"," ")).toList();}}
